class Solution {
public:
    vector<vector<string>> solveNQueens(int n) {
        vector<vector<string>> res;
        vector<string> board(n, string(n, '.'));
        function<bool(int,int)> isSafe = [&](int r, int c) {
            for (int i = 0; i < r; ++i) if (board[i][c] == 'Q') return false;
            for (int i = r-1, j = c-1; i >= 0 && j >= 0; --i, --j) if (board[i][j] == 'Q') return false;
            for (int i = r-1, j = c+1; i >= 0 && j < n; --i, ++j) if (board[i][j] == 'Q') return false;
            return true;
        };
        function<void(int)> backtrack = [&](int r) {
            if (r == n) { res.push_back(board); return; }
            for (int c = 0; c < n; ++c) {
                if (isSafe(r, c)) {
                    board[r][c] = 'Q';
                    backtrack(r + 1);
                    board[r][c] = '.';
                }
            }
        };
        backtrack(0);
        return res;
    }
};

