class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> res = new ArrayList<>();
        char[][] board = new char[n][n];
        for (char[] row : board) Arrays.fill(row, '.');
        backtrack(0, n, board, res);
        return res;
    }
    private void backtrack(int r, int n, char[][] board, List<List<String>> res) {
        if (r == n) {
            List<String> copy = new ArrayList<>();
            for (char[] row : board) copy.add(new String(row));
            res.add(copy);
            return;
        }
        for (int c = 0; c < n; c++) {
            if (isSafe(r, c, n, board)) {
                board[r][c] = 'Q';
                backtrack(r + 1, n, board, res);
                board[r][c] = '.';
            }
        }
    }
    private boolean isSafe(int r, int c, int n, char[][] board) {
        for (int i = 0; i < r; i++) if (board[i][c] == 'Q') return false;
        for (int i = r-1, j = c-1; i >= 0 && j >= 0; i--, j--) if (board[i][j] == 'Q') return false;
        for (int i = r-1, j = c+1; i >= 0 && j < n; i--, j++) if (board[i][j] == 'Q') return false;
        return true;
    }
}

