class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> res = new ArrayList<>();
        char[][] board = new char[n][n];
        for (char[] row : board) Arrays.fill(row, '.');
        backtrack(0, 0, 0, 0, n, board, res);
        return res;
    }
    private void backtrack(int row, int cols, int d1, int d2, int n, char[][] board, List<List<String>> res) {
        if (row == n) {
            List<String> copy = new ArrayList<>();
            for (char[] r : board) copy.add(new String(r));
            res.add(copy);
            return;
        }
        int avail = ((1 << n) - 1) & ~(cols | d1 | d2);
        while (avail != 0) {
            int bit = avail & -avail;
            int col = Integer.numberOfTrailingZeros(bit);
            board[row][col] = 'Q';
            backtrack(row + 1, cols | bit, (d1 | bit) << 1, (d2 | bit) >> 1, n, board, res);
            board[row][col] = '.';
            avail &= avail - 1;
        }
    }
}
